package cn.zj.zjmarket.test.payment;
import cn.zj.zjmarket.domain.payment.adapter.repository.*;
import cn.zj.zjmarket.domain.payment.adapter.port.*;
import cn.zj.zjmarket.domain.payment.model.valobj.*;
import cn.zj.zjmarket.domain.payment.service.impl.PaymentService;
import cn.zj.zjmarket.domain.order.adapter.port.ITradePort;
import cn.zj.zjmarket.domain.order.model.entity.*;
import cn.zj.zjmarket.domain.order.model.valobj.*;
import cn.zj.zjmarket.domain.order.service.impl.OrderService;
import cn.zj.zjmarket.domain.product.model.valobj.TrialOffer;
import cn.zj.zjmarket.types.exception.OrderFailure;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import java.util.*;
class PaymentServiceTest {
 static String time(long t){return PaymentService.time(t);}
 static ReservationEvidence evidence(long server){return new ReservationEvidence("RESERVATION","a-order","order","user","s","c","1","sku","1",1,"team","10.00","1.00","9.00","CNY",time(10000),time(900000),"RESERVED","FORMING","1","1",time(server),null,false,false);}
 static MarketOrder order(){return new MarketOrder("order","intent","hash",new PurchaseConfirmation("confirm","user","s","c",new PurchaseConditions("sku","OPEN",null,new TrialOffer("1","sku","1","10.00","1.00","9.00","CNY",2)),"item",null,1,300001,1L),"WAITING_PAYMENT",2,1,300001,true,"POSSIBLY_OPENED",evidence(15000),15000,false,null);}
 static Evidence clock(long start,long finish,long nano,long server){return new Evidence(evidence(server),start,finish,nano,2000,2000,2000);}
 @Test void conservativeWindowAndFreshness(){var e=clock(15000,15050,50000000,15025);assertDoesNotThrow(()->e.validate(order(),15050));assertThrows(OrderFailure.class,()->e.validate(order(),17051));assertThrows(OrderFailure.class,()->clock(10000,10000,0,10000).validate(order(),10000));assertThrows(OrderFailure.class,()->clock(897990,898000,10000000,898000).validate(order(),898000));}
 @Test void clockJumpSkewAndMonotonicRttReject(){for(var e:List.of(clock(15050,15000,0,15000),clock(15000,15001,3000000000L,15000),clock(15000,15001,1000000,18000),clock(15000,18001,1000000,15000)))assertThrows(OrderFailure.class,()->e.validate(order(),e.finished()));}
 @Test void monotonicAgeRejectsEvenWhenDatabaseClockDoesNotAdvance(){var e=new Evidence(evidence(15000),15000,15000,0,2000,2000,2000,System.nanoTime()-3_000_000_000L);assertThrows(OrderFailure.class,()->e.validate(order(),15000));assertThrows(OrderFailure.class,()->clock(15000,17000,2000000001L,16000).validate(order(),17000));}
 @Test void originalReplayDoesNotCallAOrRequireCheckout(){var repo=mock(IPaymentRepository.class);var remote=mock(ITradePort.class);var channel=mock(ISimulatedChannel.class);when(repo.order("user","order")).thenReturn(order());var receipt=new Receipt("key","CREATE_ATTEMPT","order","payment","attempt",true,15000,null);when(repo.operation("user","key")).thenReturn(new Operation(OrderService.hash("CREATE_ATTEMPT","order","NULL"),receipt,"APPLIED"));var actual=new PaymentService(repo,channel,remote,false,2000,2000,2000).create("user","order","key",null,"request");assertTrue(actual.replay());assertEquals(receipt,actual.receipt());verifyNoInteractions(remote,channel);}
 @Test void sameKeyDifferentPredecessorConflictsBeforeA(){var repo=mock(IPaymentRepository.class);var remote=mock(ITradePort.class);when(repo.order("user","order")).thenReturn(order());when(repo.operation("user","key")).thenReturn(new Operation(OrderService.hash("CREATE_ATTEMPT","order","NULL"),null,"PENDING"));assertEquals("IDEMPOTENCY_CONFLICT",assertThrows(OrderFailure.class,()->new PaymentService(repo,mock(ISimulatedChannel.class),remote,true,2000,2000,2000).create("user","order","key","other","request")).code());verifyNoInteractions(remote);}
 @Test void knownChannelSuccessRecoversWithCheckoutDisabledWithoutA(){var repo=mock(IPaymentRepository.class);var channel=mock(ISimulatedChannel.class);var remote=mock(ITradePort.class);var p=new Payment("payment","order","user",1,"UNKNOWN","OPEN","NOT_SENT","9.00","CNY",900000,null,"attempt",null,false,null);var a=new Attempt("attempt","payment",1,1,"UNKNOWN","9.00",900000,null,null,null);var w=new Work("payment","attempt","user","order","CHOOSE_RESULT","SUCCEEDED",1,"token");var fact=new Channel("payment","attempt","SUCCEEDED","channel","9.00","CNY",18000L);when(repo.due(20)).thenReturn(List.of("payment"));when(repo.claim("payment")).thenReturn(w);when(repo.payment("user","payment")).thenReturn(p);when(repo.attempt("payment","attempt")).thenReturn(a);when(channel.query("payment","attempt")).thenReturn(fact);new PaymentService(repo,channel,remote,false,2000,2000,2000).tick(20);verify(repo).finish(w,fact);verifyNoInteractions(remote);verify(channel,never()).choose(any(),any(),any(),any(),any());}
 @Test void disabledCheckoutRejectsNewKey(){var repo=mock(IPaymentRepository.class);var remote=mock(ITradePort.class);when(repo.order("user","order")).thenReturn(order());assertEquals("PAYMENT_DISABLED",assertThrows(OrderFailure.class,()->new PaymentService(repo,mock(ISimulatedChannel.class),remote,false,2000,2000,2000).create("user","order","new-key",null,"request")).code());verifyNoInteractions(remote);}
 @Test void invalidSettingsAndResultHaveNoSideEffect(){assertThrows(IllegalArgumentException.class,()->new PaymentService(null,null,null,true,0,2000,2000));var repo=mock(IPaymentRepository.class);assertThrows(OrderFailure.class,()->new PaymentService(repo,null,null,true,2000,2000,2000).choose("user","payment","attempt","key","UNKNOWN","request"));verifyNoInteractions(repo);}
 static MarketOrder closed(){var o=order();var marker=new ReservationEvidence("CLOSE_MARKER",null,"order","user","s","c",null,null,null,null,null,null,null,null,null,null,null,"CANCELLED",null,"1",null,time(16000),time(15000),false,false);return new MarketOrder(o.orderId(),o.purchaseIntentId(),o.requestHash(),o.confirmation(),"CLOSED",3,1,300001,true,"NEVER_OPENED",marker,16000,false,null,15000L,"A_CONFIRMED");}
 @Test void closedMarkerQueryNeedsNoPaymentWindow(){var repo=mock(IPaymentRepository.class);when(repo.order("user","order")).thenReturn(closed());var result=new PaymentService(repo,null,null,true,2000,2000,2000).forOrder("user","order");assertNull(result.get("payment"));assertEquals(false,result.get("canCreateAttempt"));verify(repo,never()).now();}
 @Test void definitivelyClosedNewWriteIsRejectedWithoutCallingA(){var repo=mock(IPaymentRepository.class);var port=mock(ITradePort.class);when(repo.order("user","order")).thenReturn(closed());var receipt=new Receipt("key","CREATE_ATTEMPT","order",null,null,false,16000,"PAYMENT_NOT_ALLOWED");when(repo.accept(eq("user"),eq("order"),isNull(),isNull(),eq("key"),isNull(),isNull(),anyString(),isNull())).thenReturn(new Accepted(receipt,false));assertFalse(new PaymentService(repo,null,port,true,2000,2000,2000).create("user","order","key",null,"request").receipt().accepted());verifyNoInteractions(port);}

}
